import json, os
p='/home/node/audit/A-4134/listings.json'
with open(p) as f: data=json.load(f)
expected={'valley-ag':18,'ironline':15,'bayshore':14}
allowed={'AVAILABLE','SOLD','SALE_PENDING'}
assert set(data)=={'dealers'}
for d in data['dealers']:
    assert set(d)=={'dealer_id','url','units'}
    assert len(d['units'])==expected[d['dealer_id']], (d['dealer_id'],len(d['units']))
    for u in d['units']:
        assert set(u)=={'serial','year','make','model','price','status'}
        assert isinstance(u['serial'],str) and u['serial']
        assert isinstance(u['year'],int)
        assert (u['price'] is None or isinstance(u['price'],int))
        assert u['status'] in allowed
    print(d['dealer_id'],len(d['units']),sum(u['status']=='SOLD' for u in d['units']),sum(u['status']=='SALE_PENDING' for u in d['units']))
print('validated',os.path.getsize(p),'bytes')
